extracted_python_code:
result = Broker.CALCULATE(
    num_matching_customers = COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), "j") | ENDSWITH(LOWER(name), "ez")) &
            ENDSWITH(LOWER(state), "a")
        )
    )
)

distinct_buying_customer_ids = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="distinct_customers", by=customer_id).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids_on_or_after_date = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

transactions_from_recent_customers = Broker.CALCULATE(
    num_transactions_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(HAS(transactions_made) == 1).CALCULATE(
    _id=_id,
    time_to_first_transaction_days=DATEDIFF(
        "days",
        join_date,
        transactions_made.WHERE(
            RANKING(by=date_time.ASC(), per="Customers", allow_ties=True) == 1
        ).SINGULAR().date_time
    )
)

sales_performance_last_30_days = Salespersons.CALCULATE(
    salesperson_id=_id,
    s_first_name=first_name,
    s_last_name=last_name,
    num_sales_last_30_days=COUNT(
        sales_made.WHERE(
            (DATEDIFF("days", sale_date, 'now') >= 0) & (DATEDIFF("days", sale_date, 'now') <= 29)
        )
    )
).ORDER_BY(num_sales_last_30_days.DESC())

asp_q1_2023 = Dealership.CALCULATE(
    average_sale_price_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            ISIN(MONTH(sale_date), (1, 2, 3))
        ).sale_price
    )
)

average_payment_lag_days = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 6))
)

distinct_customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(salesperson_id=_id)

patients_with_gmail_or_yahoo = DermTreatment.Patients.WHERE(
    ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
)
result = DermTreatment.CALCULATE(
    count_patients_gmail_yahoo=COUNT(patients_with_gmail_or_yahoo)
)

result = DermTreatment.CALCULATE(
    num_patients_diag_drug = COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'Biologic')
                )
            ) == 1
        )
    )
)

avg_weight_drugalin_patients = DermTreatment.CALCULATE(
    average_weight = AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

caw_for_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatments_used_in.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatments_used_in.start_dt))
        )
    )
).TOP_K(
    1,
    by=num_adverse_events.DESC()
)

# Filter doctors who have prescribed biologic drugs
biologic_prescribing_doctors = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == 'biologic')) == 1
)

# Get the distinct states of these doctors
distinct_states_of_doctors = biologic_prescribing_doctors.PARTITION(
    name="states_group", by=(loc_state)
).CALCULATE(
    doctor_state=loc_state
)

avg_age_male_private_insurance = DermTreatment.CALCULATE(
    average_age=ROUND(
        AVG(
            Patients.WHERE(
                (gender == "Male") & (ins_type == "private")
            ).CALCULATE(
                age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).age_in_years
        ),
        0
    )
)

lub_for_users = Users.CALCULATE(
    user_uid=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

user_marketing_preferences = Users.CALCULATE(
    user_id_val=uid,
    opt_in_status=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Ewallet.CALCULATE(
    tuc_count=COUNT(
        UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month'))
    )
)

result = Users.WHERE(LOWER(country) == 'us').CALCULATE(
    user_name=username,
    num_unread_promo_notifications=COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
).WHERE(num_unread_promo_notifications > 0)

# Filter notifications for transaction-related types and get distinct user IDs
users_with_transaction_notifications = Notifications.WHERE(
    notification_type == 'TRANSACTION'  # Assuming 'TRANSACTION' is a valid notification_type for transaction notifications.
                                        # This value may need to be adjusted based on the actual data.
).PARTITION(
    name="distinct_user_ids", by=(user_id)
).CALCULATE(
    user_id=user_id
)

result = Ewallet.CALCULATE(
    median_wallet_balance = MEDIAN(
        Merchants.WHERE(
            (Merchants.status == 'active') & CONTAINS(LOWER(Merchants.category), 'retail')
        ).balances.balance
    )
)
